exercise.solution:
use std::collections::HashMap;

fn split_words(text: &str) -> Vec<String> {
    let mut words = Vec::new();
    for word in text.split_whitespace() {
        words.push(word.to_lowercase());
    }
    words
}

fn word_counts(words: &[String]) -> HashMap<String, u32> {
    let mut counts = HashMap::new();
    for word in words {
        *counts.entry(word.clone()).or_insert(0) += 1;
    }
    counts
}

fn count_of(counts: &HashMap<String, u32>, word: &str) -> u32 {
    *counts.get(word).unwrap_or(&0)
}

fn main() {
    let words = split_words("The cat and the hat and THE end");
    println!("{} words", words.len());

    let counts = word_counts(&words);
    let mut keys: Vec<_> = counts.keys().collect();
    keys.sort();
    for key in keys {
        println!("{key}: {}", counts[key]);
    }
    println!("the appears {} times", count_of(&counts, "the"));
    println!("dog appears {} times", count_of(&counts, "dog"));

    let spaced = split_words("  spaced   out ");
    for word in &spaced {
        println!("[{word}]");
    }
    let empty = split_words("");
    println!("{} words, {} different", empty.len(), word_counts(&empty).len());
}
